fn main( ${shaderData.attributes} ) {

	// system
	instanceIndex = globalId.x
		+ globalId.y * ( u32(${workgroupSizeX}) * numWorkgroups.x )
		+ globalId.z * ( u32(${workgroupSizeX}) * numWorkgroups.x ) * ( u32(${workgroupSizeY}) * numWorkgroups.y );
```

